package com.termux.app.workspace;

import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiEnvironmentTest {
    @After public void cleanupState(){File f=LocalAiEnvironment.state(RuntimeEnvironment.application);f.delete();new File(f+".bak").delete();}
    static Path fixture()throws Exception{return Files.createTempDirectory(new File("build").toPath(),"local-env-").toAbsolutePath();}
    static void clean(Path base)throws Exception{try(java.util.stream.Stream<Path> all=Files.walk(base)){all.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new RuntimeException(e);}});}}
    @Test public void onlyExplicitMainTermuxOrDedicatedUbuntuCanRunTools()throws Exception{for(String old:new String[]{"ubuntu","proot:ubuntu","proot:debian","proot:jobs-local-ai-other","ssh",""}){assertFalse(LocalAiEnvironment.valid(old));WorkspaceStore.Session p=new WorkspaceStore.Session();p.localEnvironment=old;p.localAccess="read";try{LocalAiTools.authorize(p,new JSONObject().put("tool","list").put("path","."));fail(old);}catch(SecurityException expected){assertTrue(expected.getMessage().contains("RESELECT"));}}assertTrue(LocalAiEnvironment.valid("termux"));assertTrue(LocalAiEnvironment.valid(LocalAiEnvironment.UBUNTU));}
    @Test public void installUsesFreshNamedImageAndNeverResetOrClone()throws Exception{String modern=LocalAiEnvironment.installCommand("--name --architecture"),legacy=LocalAiEnvironment.installCommand("--override-alias");assertTrue(modern.contains("--name 'jobs-local-ai' ubuntu:24.04"));assertTrue(legacy.contains("--override-alias 'jobs-local-ai' ubuntu"));for(String text:new String[]{modern,legacy}){assertFalse(text.contains("reset"));assertFalse(text.contains("remove"));assertFalse(text.contains("restore"));}try{LocalAiEnvironment.installCommand("old install without alias support");fail();}catch(IllegalArgumentException expected){}}
    @Test public void onlyDedicatedEnvironmentRoutingAddsIsolation()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=LocalAiEnvironment.INTERNAL;String command=ProjectFiles.command(p,"printf hello");assertTrue(command.contains("--isolated"));assertTrue(command.contains("jobs-local-ai"));assertTrue(command.contains("LOCAL_ENVIRONMENT_NOT_READY"));assertFalse(command.contains("--termux-home"));assertFalse(command.contains("--shared-tmp"));p.environment=LocalAiEnvironment.UBUNTU;assertFalse(ProjectFiles.command(p,"true").contains("--isolated"));p.environment="ubuntu";assertTrue(ProjectFiles.command(p,"true").startsWith("proot-distro login ubuntu"));p.environment="termux";assertTrue(ProjectFiles.command(p,"true").startsWith("bash --noprofile"));}
    @Test public void containerCannotRedirectToWorkingUbuntuRoot()throws Exception{Path base=fixture();try{Path runtime=Files.createDirectory(base.resolve("runtime")),working=Files.createDirectories(runtime.resolve("containers/ubuntu/rootfs")),alias=Files.createDirectories(runtime.resolve("containers/jobs-local-ai"));Files.createSymbolicLink(alias.resolve("rootfs"),working);try{LocalAiEnvironment.root(runtime.toFile());fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("UNSAFE_LINK"));}}finally{clean(base);}}
    @Test public void readyRequiresMatchingPrivateOwnershipAndMarker()throws Exception{Path base=fixture();try{Path root=Files.createDirectories(base.resolve("containers/jobs-local-ai/rootfs"));Files.createDirectories(root.resolve("etc"));String token="00000000-0000-4000-8000-000000000001";Files.write(root.resolve("etc/termux-jobs-local-ai-owner"),token.getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("etc/termux-jobs-local-ai-ready"),new byte[]{1});File file=LocalAiEnvironment.state(RuntimeEnvironment.application);file.getParentFile().mkdirs();JSONObject record=new JSONObject().put("alias",LocalAiEnvironment.ALIAS).put("status","ready").put("root",root.toString()).put("token",token);LocalAiFiles.atomic(file,record.toString());assertTrue(LocalAiEnvironment.ready(RuntimeEnvironment.application,base.toFile()));record.put("token","00000000-0000-4000-8000-000000000002");LocalAiFiles.atomic(file,record.toString());assertFalse(LocalAiEnvironment.ready(RuntimeEnvironment.application,base.toFile()));}finally{clean(base);}}
    @Test public void unownedAliasIsNeverAssumedReady()throws Exception{Path base=fixture();try{Files.createDirectories(base.resolve("containers/jobs-local-ai/rootfs/etc"));assertFalse(LocalAiEnvironment.ready(RuntimeEnvironment.application,base.toFile()));}finally{clean(base);}}
    @Test public void setupShellSyntaxIsValidWithoutRunningInstaller()throws Exception{for(String script:new String[]{LocalAiEnvironment.bootstrap(),LocalAiEnvironment.login("printf '%s' 'a b'"),LocalAiEnvironment.command("printf '$HOME'")}){Process process=new ProcessBuilder("/bin/bash","-n","-c",script).redirectErrorStream(true).start();assertEquals(0,process.waitFor());}assertTrue(LocalAiEnvironment.bootstrap().contains("python3 git"));assertTrue(LocalAiPackages.known("python3-pip"));}
    @Test public void mainTermuxFallbackIsNotInsertedForUnavailableUbuntu(){String command=LocalAiEnvironment.command("python3 -V");assertFalse(command.contains("|| bash"));assertFalse(command.contains("login ubuntu"));assertTrue(command.contains("exit 2"));}
 @Test public void guestScriptIsPassedAsDataAndNeverExecutedByHostFallback()throws Exception{Path base=fixture();try{Path bin=Files.createDirectory(base.resolve("bin")),fake=bin.resolve("proot-distro"),unwanted=base.resolve("must-not-exist");Files.write(fake,"#!/bin/sh\nprintf '%s\\n' \"$@\"\n".getBytes(StandardCharsets.UTF_8));fake.toFile().setExecutable(true);String command=LocalAiEnvironment.command("echo $(touch "+unwanted+")");ProcessBuilder builder=new ProcessBuilder("/bin/bash","--noprofile","--norc","-c",command).redirectErrorStream(true);builder.environment().put("PATH",bin+":/usr/bin:/bin");Process process=builder.start();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[1024];int n;while((n=process.getInputStream().read(bytes))!=-1)out.write(bytes,0,n);assertEquals(0,process.waitFor());String args=out.toString("UTF-8");assertTrue(args.contains("--isolated"));assertTrue(args.contains("jobs-local-ai"));assertFalse(args.contains("\nubuntu\n"));assertFalse(Files.exists(unwanted));}finally{clean(base);}}
}
